//! The Go bridge for `internal/article/`, generated by rust-anything from `src/port.rs`: a JSON
//! dispatcher over the port, and its entry point. Regenerate with `rust-anything refresh`.

use std::ffi::{CStr, CString, c_char};

use serde_json::{Value, json};

pub mod port;
pub mod wire;

/// Argument `i`, decoded from JSON into the port's parameter type.
fn arg<T: serde::de::DeserializeOwned>(args: &[Value], i: usize) -> Result<T, String> {
    serde_json::from_value(args.get(i).cloned().unwrap_or(Value::Null))
        .map_err(|e| format!("argument {i}: {e}"))
}

/// A float argument: JSON has no NaN or infinities, so they arrive as `{"$num": "NaN"}`.
#[allow(dead_code)]
fn num(args: &[Value], i: usize) -> Result<f64, String> {
    match args.get(i) {
        Some(Value::Object(o)) => match o.get("$num").and_then(Value::as_str) {
            Some("NaN") => Ok(f64::NAN),
            Some("Infinity") => Ok(f64::INFINITY),
            Some("-Infinity") => Ok(f64::NEG_INFINITY),
            Some("-0") => Ok(-0.0),
            _ => Err(format!("argument {i}: not a number")),
        },
        _ => arg(args, i),
    }
}

#[allow(dead_code)]
fn num_vec(args: &[Value], i: usize) -> Result<Vec<f64>, String> {
    match args.get(i) {
        Some(Value::Array(items)) => (0..items.len()).map(|j| num(items, j)).collect(),
        _ => arg(args, i),
    }
}

#[allow(dead_code)]
fn opt_num(args: &[Value], i: usize) -> Result<Option<f64>, String> {
    match args.get(i) {
        None | Some(Value::Null) => Ok(None),
        Some(_) => num(args, i).map(Some),
    }
}

#[allow(dead_code)]
fn out_num(x: f64) -> Value {
    if x.is_nan() {
        json!({"$num": "NaN"})
    } else if x.is_infinite() {
        json!({"$num": if x > 0.0 { "Infinity" } else { "-Infinity" }})
    } else if x == 0.0 && x.is_sign_negative() {
        json!({"$num": "-0"})
    } else {
        json!(x)
    }
}

fn dispatch(name: &str, args: &[Value]) -> Result<Value, String> {
    match name {
        "EncodeWire" => {
            let out = port::encode_wire(
                arg(args, 0)?,
                arg(args, 1)?,
                arg(args, 2)?,
                arg(args, 3)?,
                arg(args, 4)?,
                arg(args, 5)?,
                arg(args, 6)?,
                arg(args, 7)?,
            )?;
            Ok(serde_json::to_value(out).map_err(|e| e.to_string())?)
        }
        "GenerateMessageID" => {
            let out = port::generate_message_id()?;
            Ok(serde_json::to_value(out).map_err(|e| e.to_string())?)
        }
        "GenerateFrom" => {
            let out = port::generate_from()?;
            Ok(serde_json::to_value(out).map_err(|e| e.to_string())?)
        }
        "GenerateSubject" => {
            let out = port::generate_subject(
                arg(args, 0)?,
                arg(args, 1)?,
                arg(args, 2)?,
                arg(args, 3)?,
                arg(args, 4)?,
            )?;
            Ok(serde_json::to_value(out).map_err(|e| e.to_string())?)
        }
        "GenerateRandomSubject" => {
            let out = port::generate_random_subject()?;
            Ok(serde_json::to_value(out).map_err(|e| e.to_string())?)
        }
        "GenerateRandomFilename" => {
            let out = port::generate_random_filename()?;
            Ok(serde_json::to_value(out).map_err(|e| e.to_string())?)
        }
        _ => Err(format!("no function `{name}`")),
    }
}

/// Runs `name` on the JSON array `args`; never unwinds into the caller.
pub fn call_json(name: &str, args: &str) -> String {
    let result = std::panic::catch_unwind(|| {
        let args: Vec<Value> = serde_json::from_str(args).map_err(|e| e.to_string())?;
        dispatch(name, &args)
    });
    match result {
        Ok(Ok(value)) => json!({"ok": value}),
        Ok(Err(message)) => json!({"error": message}),
        Err(panic) => {
            let message = panic
                .downcast_ref::<&str>()
                .map(ToString::to_string)
                .or_else(|| panic.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "panic".into());
            json!({"panic": message})
        }
    }
    .to_string()
}

/// The C entry point: `char *rust_anything_call(const char *name, const char *args)`. Free the
/// answer with `rust_anything_free`.
///
/// # Safety
///
/// `name` and `args` must be NUL-terminated strings, valid for the call.
// SAFETY: exported unmangled under a name only rust-anything defines.
#[unsafe(no_mangle)]
// SAFETY: callers uphold the contract under `# Safety`.
pub unsafe extern "C" fn rust_anything_call(
    name: *const c_char,
    args: *const c_char,
) -> *mut c_char {
    let text = |ptr: *const c_char| -> String {
        if ptr.is_null() {
            return String::new();
        }
        // SAFETY: the caller passes NUL-terminated strings that live for the call (see above).
        unsafe { CStr::from_ptr(ptr) }
            .to_string_lossy()
            .into_owned()
    };
    let answer = call_json(&text(name), &text(args));
    // A JSON text never contains NUL: serde_json escapes it as \u0000.
    CString::new(answer).map_or(std::ptr::null_mut(), CString::into_raw)
}

/// Frees an answer of `rust_anything_call`.
///
/// # Safety
///
/// `ptr` must come from `rust_anything_call` and not be freed before; NULL is ignored.
// SAFETY: exported unmangled under a name only rust-anything defines.
#[unsafe(no_mangle)]
// SAFETY: callers uphold the contract under `# Safety`.
pub unsafe extern "C" fn rust_anything_free(ptr: *mut c_char) {
    if !ptr.is_null() {
        // SAFETY: `ptr` was made by `CString::into_raw` in `rust_anything_call` (see above).
        drop(unsafe { CString::from_raw(ptr) });
    }
}

/// The port's result, or its error message; a panic becomes an error.
#[allow(dead_code)]
fn run<T>(f: impl FnOnce() -> Result<T, String>) -> Result<T, String> {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).unwrap_or_else(|panic| {
        let text = panic
            .downcast_ref::<&str>()
            .map(ToString::to_string)
            .or_else(|| panic.downcast_ref::<String>().cloned())
            .unwrap_or_default();
        Err(format!("Rust panic: {text}"))
    })
}

/// A Go string argument.
///
/// # Safety
///
/// `ptr` points at `len` readable bytes, or `len` is 0.
#[allow(dead_code)]
// SAFETY: unsafe to call; callers uphold the contract above.
unsafe fn go_str(ptr: *const u8, len: usize) -> String {
    if len == 0 {
        return String::new();
    }
    // SAFETY: the caller passes a Go string's bytes and its length (see above).
    String::from_utf8_lossy(unsafe { std::slice::from_raw_parts(ptr, len) }).into_owned()
}

/// Reports an error through `err`.
///
/// # Safety
///
/// `err` is a valid pointer to write to.
#[allow(dead_code)]
// SAFETY: unsafe to call; callers uphold the contract above.
unsafe fn fail(err: *mut *mut c_char, message: String) -> i32 {
    let message = CString::new(message.replace('\0', " ")).unwrap_or_default();
    // SAFETY: `err` is a valid out-pointer (see above).
    unsafe { *err = message.into_raw() };
    1
}

/// `func GenerateMessageID() string`: a typed call.
///
/// # Safety
///
/// Called by the generated Go wrapper with valid pointers.
// SAFETY: exported unmangled under a name only rust-anything defines.
#[unsafe(no_mangle)]
// SAFETY: callers uphold the contract under `# Safety`.
pub unsafe extern "C" fn rust_anything_t_GenerateMessageID(
    out: *mut u8,
    out_cap: usize,
    out_len: *mut usize,
    err: *mut *mut c_char,
) -> i32 {
    match run(|| port::generate_message_id()) {
        Ok(value) => {
            let bytes = value.as_bytes();
            // SAFETY: Go passes a buffer of `out_cap` bytes and a valid `out_len`.
            unsafe {
                *out_len = bytes.len();
                if bytes.len() > out_cap {
                    return 2;
                }
                std::ptr::copy_nonoverlapping(bytes.as_ptr(), out, bytes.len());
            }
            0
        }
        // SAFETY: Go passes a valid `err`.
        Err(message) => unsafe { fail(err, message) },
    }
}

