/// `func EncodeWire(header, fileName string, fileSize, partNumber, totalParts, offset, partSize int64, body []byte) ([]byte, error)`: binary wire.
///
/// # Safety
///
/// Called by the generated Go wrapper with valid pointers.
// SAFETY: exported unmangled under a name only rust-anything defines.
#[unsafe(no_mangle)]
// SAFETY: callers uphold the contract under `# Safety`.
pub unsafe extern "C" fn rust_anything_w_EncodeWire(
    in_ptr: *const u8,
    in_len: usize,
    out: *mut u8,
    out_cap: usize,
    out_len: *mut usize,
    err: *mut *mut c_char,
) -> i32 {
    let input: &[u8] = if in_len == 0 {
        &[]
    } else {
        // SAFETY: Go passes its buffer and length.
        unsafe { std::slice::from_raw_parts(in_ptr, in_len) }
    };
    let result = run(|| {
        let r = &mut wire::Reader::new(input);
        let ra_arg0: String = r.string()?;
        let ra_arg1: String = r.string()?;
        let ra_arg2: i64 = r.i64()?;
        let ra_arg3: i64 = r.i64()?;
        let ra_arg4: i64 = r.i64()?;
        let ra_arg5: i64 = r.i64()?;
        let ra_arg6: i64 = r.i64()?;
        let ra_arg7: Vec<i64> = r.list(|r| r.i64())?;
        let w = &mut wire::Writer::default();
        let out = &port::encode_wire(
            ra_arg0, ra_arg1, ra_arg2, ra_arg3, ra_arg4, ra_arg5, ra_arg6, ra_arg7,
        )?;
        w.tag(1);
        w.count(out.len());
        for x0 in out.iter() {
            w.i64(*x0);
        }
        Ok(std::mem::take(&mut w.0))
    });
    match result {
        Ok(bytes) => {
            // SAFETY: Go passes a buffer of `out_cap` bytes and a valid `out_len`.
            unsafe {
                *out_len = bytes.len();
                if bytes.len() > out_cap {
                    return 2;
                }
                std::ptr::copy_nonoverlapping(bytes.as_ptr(), out, bytes.len());
            }
            0
        }
        // SAFETY: Go passes a valid `err`.
        Err(message) => unsafe { fail(err, message) },
    }
}
